:root {
  --bg: #0f172a;
  --card: #111827;
  --card-border: #334155;
  --text: #f8fafc;
  --muted: #94a3b8;
  --accent: #38bdf8;
  --accent-strong: #0ea5e9;
  --accent-dark: #0284c7;
  --focus: #fbbf24;
  --overlay: rgba(15, 23, 42, 0.55);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--text);
  background: radial-gradient(circle at top left, #1f2a44 0%, #0f172a 50%, #020617 100%);
}

.card {
  width: 100%;
  max-width: 760px;
  padding: 32px;
  background: linear-gradient(180deg, #111827 0%, #0b1120 100%);
  border: 1px solid var(--card-border);
  border-radius: 24px;
  box-shadow: 0 24px 48px rgba(0, 0, 0, 0.45);
  text-align: center;
}

h1 {
  margin: 0 0 8px;
  font-size: clamp(1.8rem, 5vw, 2.4rem);
  line-height: 1.15;
  letter-spacing: -0.02em;
}

.subtitle {
  margin: 0 0 28px;
  color: var(--muted);
  font-size: 1rem;
}

.palette {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(125px, 1fr));
  gap: 14px;
  margin-bottom: 28px;
}

.swatch {
  min-height: 135px;
  border-radius: 18px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: flex-start;
  background-color: #000;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.12), 0 10px 20px rgba(0, 0, 0, 0.28);
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.swatch:hover {
  transform: translateY(-2px);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.18), 0 14px 24px rgba(0, 0, 0, 0.34);
}

.hex {
  display: inline-block;
  padding: 4px 8px;
  border-radius: 8px;
  background: var(--overlay);
  color: #ffffff;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.45);
}

.lock-btn {
  align-self: flex-end;
  width: 44px;
  height: 44px;
  border-radius: 999px;
  background: var(--overlay);
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.35);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  line-height: 1;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
}

.lock-btn:hover {
  background: rgba(15, 23, 42, 0.75);
  border-color: rgba(255, 255, 255, 0.6);
}

.lock-btn:focus-visible,
.generate-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.lock-btn:active {
  transform: scale(0.92);
}

.lock-btn[aria-pressed="true"] {
  background: rgba(15, 23, 42, 0.85);
  border-color: var(--focus);
  box-shadow: 0 0 0 2px rgba(251, 191, 36, 0.3);
}

.generate-btn {
  width: 100%;
  padding: 14px 20px;
  border-radius: 14px;
  border: 1px solid var(--accent);
  background: var(--accent-strong);
  color: #082f49;
  font-size: 1.1rem;
  font-weight: 800;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
}

.generate-btn:hover {
  background: var(--accent);
  border-color: #7dd3fc;
}

.generate-btn:active {
  transform: scale(0.98);
  background: var(--accent-dark);
}

@media (max-width: 520px) {
  body {
    padding: 12px;
  }

  .card {
    padding: 20px 16px;
    border-radius: 20px;
  }

  .palette {
    gap: 10px;
    grid-template-columns: repeat(2, 1fr);
  }

  .swatch {
    min-height: 110px;
    padding: 10px;
    border-radius: 14px;
  }

  .swatch:last-child:nth-child(odd) {
    grid-column: span 2;
  }

  .hex {
    font-size: 0.85rem;
  }

  .lock-btn {
    width: 40px;
    height: 40px;
    font-size: 1.1rem;
  }

  .generate-btn {
    padding: 13px 16px;
    font-size: 1rem;
  }
}

"use strict";

const paletteEl = document.getElementById("palette");
const generateBtn = document.getElementById("generateBtn");

const palette = Array.from({ length: 5 }, () => ({ hex: "#000000", locked: false }));

const OFFSETS = [0, 30, 62, 180, 210];

function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function hslToHex(h, s, l) {
  s /= 100;
  l /= 100;
  const k = (n) => (n + h / 30) % 12;
  const a = s * Math.min(l, 1 - l);
  const f = (n) => l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
  const toHex = (x) => Math.round(255 * x).toString(16).padStart(2, "0");
  return `#${toHex(f(0))}${toHex(f(8))}${toHex(f(4))}`;
}

function hexToHsl(hex) {
  const r = parseInt(hex.slice(1, 3), 16) / 255;
  const g = parseInt(hex.slice(3, 5), 16) / 255;
  const b = parseInt(hex.slice(5, 7), 16) / 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  let h = 0;
  let s = 0;
  const l = (max + min) / 2;

  if (max !== min) {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);

    if (max === r) {
      h = ((g - b) / d + (g < b ? 6 : 0)) * 60;
    } else if (max === g) {
      h = ((b - r) / d + 2) * 60;
    } else {
      h = ((r - g) / d + 4) * 60;
    }
  }

  return { h: Math.round(h), s: Math.round(s * 100), l: Math.round(l * 100) };
}

function renderPalette() {
  paletteEl.innerHTML = "";

  palette.forEach((color, index) => {
    const swatch = document.createElement("div");
    swatch.className = "swatch";
    swatch.style.backgroundColor = color.hex;
    swatch.setAttribute("role", "listitem");

    const hexLabel = document.createElement("span");
    hexLabel.className = "hex";
    hexLabel.textContent = color.hex.toUpperCase();

    const lockButton = document.createElement("button");
    lockButton.type = "button";
    lockButton.className = "lock-btn";
    lockButton.setAttribute("aria-pressed", String(color.locked));
    lockButton.setAttribute("aria-label", `${color.locked ? "Unlock" : "Lock"} ${color.hex.toUpperCase()}`);
    lockButton.textContent = color.locked ? "🔒" : "🔓";
    lockButton.addEventListener("click", () => {
      color.locked = !color.locked;
      renderPalette();
    });

    swatch.append(hexLabel, lockButton);
    paletteEl.appendChild(swatch);
  });
}

function generatePalette() {
  const lockedColors = palette.filter((color) => color.locked);
  let baseHue = randomInt(0, 360);
  let saturation = randomInt(58, 72);
  let lightness = randomInt(45, 62);

  if (lockedColors.length > 0) {
    const firstLock = hexToHsl(lockedColors[0].hex);
    baseHue = firstLock.h;
    saturation = firstLock.s;
    lightness = firstLock.l;
  }

  palette.forEach((color, index) => {
    if (color.locked) return;

    const hue = (baseHue + OFFSETS[index]) % 360;
    const s = Math.min(100, Math.max(35, saturation + randomInt(-4, 4)));
    const l = Math.min(80, Math.max(28, lightness + randomInt(-4, 4)));
    color.hex = hslToHex(hue, s, l);
  });

  renderPalette();
}

generateBtn.addEventListener("click", generatePalette);

// Create the initial palette on page load.
generatePalette();
